from scipy.optimize import least_squares
shapes={
 'x*exp(-bx)':lambda x,b: x*np.exp(-b*x),
 'x*exp(-bx^2)':lambda x,b: x*np.exp(-b*x*x),
 'x/(1+bx^2)':lambda x,b: x/(1+b*x*x),
 'x/(1+bx)^2':lambda x,b: x/(1+b*x)**2,
 'x*exp(-b*x)+x^3':lambda x,b: x*np.exp(-b*x)+0*x,
 'x*(1-b*x)exp(-x)':lambda x,b: x*(1-b*x)*np.exp(-x),
 'x^b':lambda x,b: np.sign(x)*np.abs(x)**b,
 'tanh(bx)':lambda x,b: np.tanh(b*x),
}
for name,f in shapes.items():
    def model(p):
        w,c0,A,b,C,S,D=p
        return c0 + A*f(x,b) + C*np.cos(w*t) + S*np.sin(w*t) + D*v
    best=None
    for w0 in [0.13,0.3,0.5]:
      for b0 in [0.3,0.72,1.5,3.0]:
        try:
            rr=least_squares(lambda p: model(p)-dv_dt, [w0,-5,20,b0,8,-2,0])
            if best is None or rr.cost<best.cost: best=rr
        except Exception: pass
    print(name, np.round(best.x,4), '%.3e'%(np.sum(best.fun**2)/np.sum((dv_dt-dv_dt.mean())**2)))

from scipy.optimize import least_squares
def run(kind):
    def model(p):
        w,c0,A,b,C,S,D,q=p
        if kind=='chirp':
            ph=w*t+q*t*t
            return c0 + A*x*np.exp(-b*x) + C*np.cos(ph) + S*np.sin(ph) + D*v
        if kind=='env':
            e=np.exp(-q*t)
            return c0 + A*x*np.exp(-b*x) + e*(C*np.cos(w*t) + S*np.sin(w*t)) + D*v
        if kind=='const_env_sqrt':
            return c0 + A*x*np.exp(-b*x) + (C*np.cos(w*t) + S*np.sin(w*t))*np.sqrt(np.abs(q)+t)+ D*v
    best=None
    for w0 in [0.13,0.3,0.5]:
      for q0 in [-0.1,0.01,-0.3,0.3]:
        try:
            rr=least_squares(lambda p: model(p)-dv_dt, [w0,-5,27,0.72,5,-1,0,q0])
            if best is None or rr.cost<best.cost: best=rr
        except Exception: pass
    print(kind, np.round(best.x,6), '%.3e'%(np.sum(best.fun**2)/np.sum((dv_dt-dv_dt.mean())**2)))
run('chirp'); run('env'); run('const_env_sqrt')
